class Solution {
  public long minEnergy(int n, int brightness, int[][] intervals) {
    int[][] sorted = intervals.clone();
    java.util.Arrays.sort(sorted, (a, b) -> Integer.compare(a[0], b[0]));
    long covered = 0, curStart = sorted[0][0], curEnd = sorted[0][1];
    for (int i = 1; i < sorted.length; i++) {
      if (sorted[i][0] <= curEnd + 1L) {
        curEnd = Math.max(curEnd, sorted[i][1]);
      } else {
        covered += curEnd - curStart + 1;
        curStart = sorted[i][0];
        curEnd = sorted[i][1];
      }
    }
    covered += curEnd - curStart + 1;
    return covered * ((brightness + 2) / 3);
  }
}
